<?php defined('ABSPATH') || exit; $c=get_option('nem_home_content', []); $shop=wc_get_page_permalink('shop'); ?>
<!doctype html><html <?php language_attributes(); ?>><head><meta charset="<?php bloginfo('charset'); ?>"><meta name="viewport" content="width=device-width, initial-scale=1"><?php wp_head(); ?></head>
<body <?php body_class('nem-home'); ?>><?php wp_body_open(); ?>
<a class="skip-link screen-reader-text" href="#main">Đến nội dung</a>
<header class="nem-header"><a class="nem-logo" href="<?php echo esc_url(home_url('/')); ?>" aria-label="NEM trang chủ"><?php nem_image($c['images']['logo']); ?></a>
<button class="menu-toggle" aria-expanded="false" aria-controls="nem-nav">☰ <span>Menu</span></button><nav id="nem-nav" aria-label="Menu chính"><?php foreach($c['menu'] as $m): ?><a href="<?php echo esc_url($m['url']); ?>"><?php echo esc_html($m['title']); ?></a><?php endforeach; ?></nav>
<div class="header-actions"><button class="search-toggle" aria-label="Mở tìm kiếm" aria-expanded="false">⌕</button><a href="<?php echo esc_url(wc_get_page_permalink('myaccount')); ?>">◎ <span>Tài khoản</span></a><a href="<?php echo esc_url(wc_get_cart_url()); ?>">♙ <span>Giỏ hàng</span> <b><?php echo WC()->cart ? (int)WC()->cart->get_cart_contents_count() : 0; ?></b></a></div>
<form class="nem-search" role="search" action="<?php echo esc_url(home_url('/')); ?>" hidden><input type="hidden" name="post_type" value="product"><input type="search" name="s" placeholder="Tìm kiếm sản phẩm…" aria-label="Tìm kiếm sản phẩm"><button>Tìm kiếm</button></form></header>
<main id="main"><section class="hero" aria-label="Ưu đãi nổi bật" aria-roledescription="carousel"><?php foreach(['hero','hero3','hero4'] as $i=>$key): if(empty($c['images'][$key])) continue; ?><a class="hero-slide" href="<?php echo esc_url($c['hero_url']); ?>" <?php if($i) echo 'hidden'; ?> aria-label="Banner <?php echo $i+1; ?>"><?php nem_image($c['images'][$key], '', $i===0); ?></a><?php endforeach; ?><button class="hero-prev" aria-label="Banner trước">←</button><button class="hero-next" aria-label="Banner tiếp theo">→</button><div class="hero-dots" aria-label="Chọn banner"><button class="active" aria-label="Banner 1" aria-pressed="true"></button><button aria-label="Banner 2" aria-pressed="false"></button><button aria-label="Banner 3" aria-pressed="false"></button></div></section>
<section class="features" aria-label="Thiết kế nổi bật"><?php foreach($c['features'] as $i=>$f): ?><a href="<?php echo esc_url($f['url']); ?>"><?php nem_image($c['images']['feature'.($i+1)], '', true); ?><div><strong><?php echo esc_html($f['title']); ?></strong><span>SHOP NOW</span></div></a><?php endforeach; ?></section>
<?php foreach($c['sections'] as $section): ?><section class="product-section nem-container"><h2><?php echo esc_html($section['title']); ?></h2><div class="product-grid"><?php foreach($section['products'] as $id): $p=wc_get_product($id); if(!$p || !$p->is_visible()) continue; ?><article class="nem-product"><a href="<?php echo esc_url($p->get_permalink()); ?>"><div class="product-image"><?php echo $p->get_image('full'); ?><?php if($p->is_on_sale()): ?><span class="store-badge">STORE ONLY</span><span class="sale-badge">-<?php echo (int)round((1-(float)$p->get_sale_price()/(float)$p->get_regular_price())*100); ?>%</span><?php endif; ?></div><h3><?php echo esc_html($p->get_name()); ?></h3></a><div class="nem-price"><?php echo wp_kses_post($p->get_price_html()); ?></div></article><?php endforeach; ?></div></section><?php endforeach; ?>
<a class="collection" href="<?php echo esc_url($c['collection_url']); ?>"><?php nem_image($c['images']['collection']); ?></a>
<section class="blog-section nem-container"><h2><?php echo esc_html($c['blog_title']); ?></h2><p><?php echo esc_html($c['blog_subtitle']); ?></p><div class="blog-grid"><?php foreach($c['posts'] as $id): ?><article><a href="<?php echo esc_url(get_permalink($id)); ?>"><?php echo get_the_post_thumbnail($id, 'full'); ?><h3><?php echo esc_html(get_the_title($id)); ?></h3></a></article><?php endforeach; ?></div></section>
<section id="newsletter" class="newsletter"><h2><?php echo esc_html($c['newsletter_title']); ?></h2><p><?php echo esc_html($c['newsletter_text']); ?></p><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><input type="hidden" name="action" value="nem_subscribe"><?php wp_nonce_field('nem_subscribe','nem_nonce'); ?><label class="screen-reader-text" for="email">Email</label><input id="email" type="email" name="email" required placeholder="Vui lòng nhập email…"><input class="honeypot" name="website" tabindex="-1" autocomplete="off" aria-hidden="true"><button>ĐĂNG KÝ</button></form><?php if(isset($_GET['newsletter'])): ?><p role="status"><?php echo $_GET['newsletter']==='success' ? 'Cảm ơn bạn! Email đã được lưu để nhận bản tin.' : 'Chưa thể đăng ký. Vui lòng kiểm tra email và thử lại.'; ?></p><?php endif; ?><div class="socials"><?php foreach($c['socials'] as $s): ?><a href="<?php echo esc_url($s['url']); ?>" aria-label="<?php echo esc_attr($s['title']); ?>"><?php echo esc_html($s['icon']); ?></a><?php endforeach; ?></div></section></main>
<footer class="nem-footer"><div class="nem-container footer-grid"><div><h3><?php echo esc_html($c['company_title']); ?></h3><p><?php echo nl2br(esc_html($c['company_text'])); ?></p></div><?php foreach($c['footer_groups'] as $group): ?><div class="footer-links"><?php foreach($group as $l): ?><a href="<?php echo esc_url($l['url']); ?>"><?php echo esc_html($l['title']); ?></a><?php endforeach; ?></div><?php endforeach; ?><div><p>Phương thức thanh toán</p><?php nem_image($c['images']['payment'],'payment'); ?><?php nem_image($c['images']['bct'],'certification'); ?></div></div></footer><div class="copyright"><?php echo esc_html($c['copyright']); ?></div><?php wp_footer(); ?></body></html>
